import re

TEXTOS_ALT_GENERICOS = {"imagem", "foto", "icone", "ícone", "image", "photo", "icon"}
TEXTOS_LINK_GENERICOS = {"clique aqui", "saiba mais", "mais", "ver", "abrir", "link"}
TITULOS_GENERICOS = {"home", "pagina", "página", "app", "react app", "document", "untitled"}
TAGS_NAO_INTERATIVAS = {"div", "span", "p", "li", "section", "article"}
EVENTOS_MOUSE = {"onmouseover", "onmouseout", "onmousedown", "onmouseup"}
EVENTOS_TECLADO = {"onfocus", "onkeydown", "onkeyup", "onkeypress"}
TAGS_TEXTO = {"p", "span", "a", "button", "li", "td", "th", "label", "strong", "em", "small"}


def achado(rec, severidade, elemento, problema, sugestao):
    return {
        "rec": rec,
        "severity": severidade,
        "element": elemento,
        "problem": problema,
        "suggestion": sugestao,
    }


def desc_elemento(elemento):
    if elemento is None:
        return ""
    nome = elemento.name or "elemento"
    if elemento.get("id"):
        return f"{nome}#{elemento.get('id')}"
    if elemento.get("upa11y-id"):
        return f"{nome}[upa11y-id={elemento.get('upa11y-id')}]"
    classes = elemento.get("class", [])
    return f"{nome}.{'.'.join(classes[:2])}" if classes else nome


def estilos_inline(elemento):
    estilos = {}
    for item in elemento.get("style", "").split(";"):
        if ":" not in item:
            continue
        chave, valor = item.split(":", 1)
        estilos[chave.strip().lower()] = valor.strip().lower()
    return estilos


def blocos_estilo(documento):
    return "\n".join(bloco.get_text(" ", strip=True) for bloco in documento.find_all("style"))


def tem_texto(elemento):
    return bool(elemento.get_text(" ", strip=True))


def texto_proximo(elemento, palavras):
    textos = [elemento.parent.get_text(" ", strip=True).lower()] if elemento.parent else []
    irmaos = list(elemento.find_previous_siblings(limit=2)) + list(elemento.find_next_siblings(limit=2))
    textos.extend(irmao.get_text(" ", strip=True).lower() for irmao in irmaos)
    texto = " ".join(textos)
    return any(palavra in texto for palavra in palavras)


def nome_acessivel(elemento, documento=None):
    if elemento.get("aria-label"):
        return elemento.get("aria-label").strip()

    rotulos = elemento.get("aria-labelledby")
    if rotulos and documento:
        textos = [rotulo.get_text(" ", strip=True) for id_item in rotulos.split() if (rotulo := documento.find(id=id_item))]
        if textos:
            return " ".join(textos).strip()

    if elemento.name in {"input", "textarea", "select"} and documento:
        id_campo = elemento.get("id")
        if id_campo and (rotulo := documento.find("label", attrs={"for": id_campo})):
            return rotulo.get_text(" ", strip=True)

        rotulo_pai = elemento.find_parent("label")
        if rotulo_pai:
            return rotulo_pai.get_text(" ", strip=True)

    if elemento.name == "img":
        return elemento.get("alt", "").strip()

    texto = elemento.get_text(" ", strip=True)
    if texto:
        return texto

    if elemento.get("title"):
        return elemento.get("title").strip()

    return ""


def texto_generico(texto, opcoes):
    return texto.strip().lower() in opcoes


def tem_altura_fixa(estilos):
    return bool(estilos.get("height") or estilos.get("max-height"))


def valor_px(valor):
    achado_px = re.search(r"(-?\d+(?:\.\d+)?)px", valor or "")
    return float(achado_px.group(1)) if achado_px else None


def tem_titulo(elemento):
    if elemento.get("aria-label") or elemento.get("aria-labelledby"):
        return True
    return elemento.find(re.compile(r"^h[1-6]$")) is not None


def nivel_titulo(elemento):
    return int(elemento.name[1])


def saltos_titulos(documento):
    saltos = []
    anterior = None
    for titulo in documento.find_all(re.compile(r"^h[1-6]$")):
        atual = nivel_titulo(titulo)
        if anterior is not None and atual > anterior + 1:
            saltos.append((titulo, anterior, atual))
        anterior = atual
    return saltos


def campos_formulario(formulario):
    return formulario.find_all(["input", "textarea", "select"])


def cor_rgb(valor):
    valor = (valor or "").strip().lower()
    cores_nomeadas = {
        "black": (0, 0, 0),
        "white": (255, 255, 255),
        "red": (255, 0, 0),
        "green": (0, 128, 0),
        "blue": (0, 0, 255),
        "gray": (128, 128, 128),
        "grey": (128, 128, 128),
    }
    if valor in cores_nomeadas:
        return cores_nomeadas[valor]

    if valor.startswith("#"):
        cor = valor[1:]
        if len(cor) == 3:
            cor = "".join(parte * 2 for parte in cor)
        if len(cor) == 6:
            try:
                return tuple(int(cor[i:i + 2], 16) for i in (0, 2, 4))
            except ValueError:
                return None

    encontrado = re.match(r"rgba?\(([^)]+)\)", valor)
    if encontrado:
        partes = [parte.strip() for parte in encontrado.group(1).split(",")[:3]]
        try:
            return tuple(int(float(parte)) for parte in partes)
        except ValueError:
            return None

    return None


def luminancia_relativa(rgb):
    valores = []
    for canal in rgb:
        valor = canal / 255
        if valor <= 0.03928:
            valores.append(valor / 12.92)
        else:
            valores.append(((valor + 0.055) / 1.055) ** 2.4)
    return valores[0] * 0.2126 + valores[1] * 0.7152 + valores[2] * 0.0722


def razao_contraste(frente, fundo):
    l1 = luminancia_relativa(frente)
    l2 = luminancia_relativa(fundo)
    mais_clara = max(l1, l2)
    mais_escura = min(l1, l2)
    return (mais_clara + 0.05) / (mais_escura + 0.05)


def texto_visivel(documento):
    copia = documento.__copy__()
    for elemento in copia(["script", "style", "noscript"]):
        elemento.decompose()
    return copia.get_text(" ", strip=True)

