REC = "REC12"


def tem_alternativa_teclado(elemento):
    if elemento.name in {"button", "a", "input", "select", "textarea", "summary"}:
        return True
    return any(elemento.has_attr(evento) for evento in EVENTOS_TECLADO)


def testar(analisador):
    documento = analisador.obter_soup()
    achados = []

    for elemento in documento.find_all(onclick=True):
        if elemento.name in TAGS_NAO_INTERATIVAS:
            achados.append(achado(
                REC,
                "error",
                desc_elemento(elemento),
                "Elemento não interativo com onclick.",
                "Usar button/link semântico ou adicionar role, tabindex e eventos de teclado.",
            ))

    for elemento in documento.find_all(True):
        if any(elemento.has_attr(evento) for evento in EVENTOS_MOUSE) and not tem_alternativa_teclado(elemento):
            achados.append(achado(
                REC,
                "warning",
                desc_elemento(elemento),
                "Evento de mouse sem alternativa de teclado detectável.",
                "Adicionar onfocus/onkeydown ou usar elemento interativo semântico.",
            ))

        tabindex = elemento.get("tabindex")
        if tabindex and tabindex.lstrip("+").isdigit() and int(tabindex) > 0:
            achados.append(achado(
                REC,
                "warning",
                desc_elemento(elemento),
                "tabindex positivo altera a ordem natural de foco.",
                "Usar tabindex=\"0\" apenas quando necessário e preservar a ordem do DOM.",
            ))

    for link in documento.find_all("a", href="#", onclick=True):
        achados.append(achado(
            REC,
            "warning",
            desc_elemento(link),
            "Link href=\"#\" com onclick parece estar sendo usado como botão.",
            "Usar <button> para ações ou um href real para navegação.",
        ))

    return achados

REC = "REC16"
TERMOS_COMPLEXOS = {"cpf", "cnpj", "telefone", "tel", "cep", "senha", "data", "convenio", "convênio", "carteirinha"}
TERMOS_AJUDA = {"exemplo", "formato", "digite", "informe", "obrigatório", "obrigatorio", "deve conter"}
TERMOS_ERRO = {"erro", "error", "inválido", "invalido", "obrigatório", "obrigatorio", "required"}


def dica_campo(campo):
    return " ".join([
        campo.get("name", ""),
        campo.get("id", ""),
        campo.get("placeholder", ""),
        campo.get("aria-label", ""),
        campo.get("title", ""),
    ]).lower()


def tem_ajuda(campo):
    if campo.get("aria-describedby") or campo.get("title"):
        return True
    if any(termo in campo.get("placeholder", "").lower() for termo in TERMOS_AJUDA):
        return True
    return texto_proximo(campo, TERMOS_AJUDA)


def ids_descritos(campo):
    return set((campo.get("aria-describedby") or "").split())


def testar(analisador):
    documento = analisador.obter_soup()
    achados = []

    campos = documento.find_all(["input", "textarea", "select"])
    for campo in campos:
        if campo.name == "input" and campo.get("type") == "hidden":
            continue

        dica = dica_campo(campo)
        eh_complexo = any(termo in dica for termo in TERMOS_COMPLEXOS)
        if eh_complexo and not tem_ajuda(campo):
            achados.append(achado(
                REC,
                "warning",
                desc_elemento(campo),
                "Campo complexo sem ajuda detectável.",
                "Adicionar instrução, exemplo, title ou aria-describedby.",
            ))

        if campo.get("pattern") and not tem_ajuda(campo):
            achados.append(achado(
                REC,
                "warning",
                desc_elemento(campo),
                "Campo com pattern sem explicação textual.",
                "Explicar o formato esperado e associar a ajuda ao campo.",
            ))

    for mensagem in documento.find_all(True):
        texto_direto = " ".join(mensagem.find_all(string=True, recursive=False))
        texto = " ".join([
            " ".join(mensagem.get("class", [])),
            mensagem.get("id", ""),
            texto_direto,
        ]).lower()
        if not any(termo in texto for termo in TERMOS_ERRO):
            continue

        associada = False
        id_mensagem = mensagem.get("id")
        if id_mensagem:
            associada = any(id_mensagem in ids_descritos(campo) for campo in campos)
        if not associada:
            associada = bool(mensagem.find_parent("label") or mensagem.find_parent("form"))
        if not associada:
            achados.append(achado(
                REC,
                "warning",
                desc_elemento(mensagem),
                "Mensagem de erro sem associação clara ao campo.",
                "Associar a mensagem via aria-describedby ou posicioná-la junto ao campo correspondente.",
            ))

    for formulario in documento.find_all("form"):
        total_campos = len([campo for campo in campos_formulario(formulario) if campo.name != "input" or campo.get("type") != "hidden"])
        texto = formulario.get_text(" ", strip=True).lower()
        tem_instrucao = any(termo in texto for termo in TERMOS_AJUDA)
        if total_campos >= 5 and not tem_instrucao:
            achados.append(achado(
                REC,
                "warning",
                desc_elemento(formulario),
                "Formulário longo sem instrução inicial detectável.",
                "Adicionar instruções antes dos campos.",
            ))

    return achados

REC = "REC19"
TERMOS_GRAFICO = {"grafico", "gráfico", "chart", "graph", "plot", "diagram", "diagrama", "fluxo", "map", "mapa"}
TERMOS_DADOS = {"dados do gráfico", "dados do grafico", "tabela de dados", "ver dados", "descrição", "descricao"}


def parece_grafico(elemento):
    valores = [
        elemento.get("src", ""),
        elemento.get("id", ""),
        " ".join(elemento.get("class", [])),
        elemento.get("alt", ""),
        elemento.get("aria-label", ""),
    ]
    texto = " ".join(valores).lower()
    return any(termo in texto for termo in TERMOS_GRAFICO)


def tem_texto_detalhado(elemento):
    figura = elemento.find_parent("figure")
    if figura and figura.find("figcaption"):
        return True
    if texto_proximo(elemento, TERMOS_DADOS):
        return True
    pai = elemento.parent
    if pai and pai.find("table"):
        return True
    return False


def testar(analisador):
    documento = analisador.obter_soup()
    achados = []

    graficos = [elemento for elemento in documento.find_all(["img", "canvas", "svg"]) if parece_grafico(elemento)]

    for imagem in [item for item in graficos if item.name == "img"]:
        alt = imagem.get("alt", "")
        if not imagem.has_attr("alt"):
            achados.append(achado(
                REC,
                "error",
                desc_elemento(imagem),
                "Imagem de gráfico sem alt.",
                "Adicionar alt que descreva o conteúdo do gráfico.",
            ))
        elif texto_generico(alt, TEXTOS_ALT_GENERICOS):
            achados.append(achado(
                REC,
                "warning",
                desc_elemento(imagem),
                "Gráfico com alt genérico.",
                "Descrever a informação principal do gráfico.",
            ))

        if not tem_texto_detalhado(imagem):
            achados.append(achado(
                REC,
                "warning",
                desc_elemento(imagem),
                "Gráfico sem tabela ou descrição textual detalhada detectável.",
                "Adicionar figcaption, tabela de dados ou link para dados do gráfico.",
            ))

    for canvas in [item for item in graficos if item.name == "canvas"]:
        if not (tem_texto(canvas) or canvas.get("aria-label") or canvas.get("aria-describedby")):
            achados.append(achado(
                REC,
                "error",
                desc_elemento(canvas),
                "Canvas gráfico sem alternativa textual.",
                "Adicionar texto interno, aria-label ou aria-describedby.",
            ))
        if not tem_texto_detalhado(canvas):
            achados.append(achado(
                REC,
                "warning",
                desc_elemento(canvas),
                "Canvas sem tabela ou descrição textual detalhada detectável.",
                "Adicionar descrição próxima ou tabela de dados.",
            ))

    for svg in [item for item in graficos if item.name == "svg"]:
        if not (svg.find("title") or svg.find("desc") or svg.get("aria-label") or svg.get("aria-labelledby")):
            achados.append(achado(
                REC,
                "error",
                desc_elemento(svg),
                "SVG gráfico sem título ou descrição.",
                "Adicionar title, desc, aria-label ou aria-labelledby.",
            ))
        if not tem_texto_detalhado(svg):
            achados.append(achado(
                REC,
                "warning",
                desc_elemento(svg),
                "SVG sem tabela ou descrição textual detalhada detectável.",
                "Adicionar descrição próxima ou tabela de dados.",
            ))

    return achados
